d=np.array(raw); x=d[:,0]; y=d[:,1]
o=np.argsort(x); xs=x[o]; ys=y[o]

def lor(x, off, A, x0, g):
    return off + A*(g*g)/((x-x0)**2+g*g)
def gau(x, off, A, x0, s):
    return off + A*np.exp(-0.5*((x-x0)/s)**2)

def fit(cen, half, model, p0g):
    m=(xs>cen-half)&(xs<cen+half)
    xx=xs[m]; yy=ys[m]
    # initial guess
    off0=np.median(np.r_[yy[:5],yy[-5:]])
    A0=yy.max()-off0
    if model is lor:
        p0=[off0,A0,cen,p0g]
    else:
        p0=[off0,A0,cen,p0g]
    popt,pcov=curve_fit(model,xx,yy,p0=p0,maxfev=20000)
    perr=np.sqrt(np.diag(pcov))
    resid=yy-model(xx,*popt)
    rmse=np.sqrt(np.mean(resid**2))
    return popt,perr,rmse,len(xx)

