sbx run <<'EOF'
cd /workspace
PYTHONPATH=/workspace/pylibs python3 - <<'PY'
import numpy as np
from scipy.optimize import curve_fit
raw=[]
for line in open('graphene.dat'):
    line=line.strip()
    if not line: continue
    a,b=line.split('\t')
    raw.append((float(a.replace(',','.')), float(b.replace(',','.'))))
d=np.array(raw); x=d[:,0]; y=d[:,1]
s=1e7/x
o=np.argsort(s); ss=s[o]; xs=x[o]; ys=y[o]

# correct: y = a + b*t + A*g^2/((t-t0)^2+g^2)
def lor_lin(t,a,b,t0,g,A):
    return a+b*t+A*g*g/((t-t0)**2+g*g)
def lor_const(t,off,t0,g,A):
    return off+A*g*g/((t-t0)**2+g*g)
def gau_lin(t,a,b,t0,sg,A):
    return a+b*t+A*np.exp(-0.5*((t-t0)/sg)**2)
def gau_const(t,off,t0,sg,A):
    return off+A*np.exp(-0.5*((t-t0)/sg)**2)

def go(tvar,cen,half,label,lin=True):
    m=(tvar>cen-half)&(tvar<cen+half)
    tt=tvar[m]; yy=ys[m]
    off0=np.median(np.r_[yy[:8],yy[-8:]])
    A0=yy.max()-off0
    if lin:
        p0=[off0,0,cen,half*0.15,A0]
        popt,pcov=curve_fit(lor_lin,tt,yy,p0=p0,maxfev=100000)
        perr=np.sqrt(np.diag(pcov))
        base=popt[0]+popt[1]*popt[2]
        r=yy-lor_lin(tt,*popt)
        print(f"{label:32s} n={len(tt):3d} off@t0={base:9.1f} A={popt[4]:9.1f} t0={popt[2]:10.4f} g={popt[3]:7.4f} rmse={np.sqrt(np.mean(r*r)):6.1f}  (+-t0 {perr[2]:.4f}, +-g {perr[3]:.4f})")
        return popt
    else:
        p0=[off0,cen,half*0.15,A0]
        popt,pcov=curve_fit(lor_const,tt,yy,p0=p0,maxfev=100000)
        perr=np.sqrt(np.diag(pcov))
        r=yy-lor_const(tt,*popt)
        print(f"{label:32s} n={len(tt):3d} off={popt[0]:9.1f} A={popt[3]:9.1f} t0={popt[1]:10.4f} g={popt[2]:7.4f} rmse={np.sqrt(np.mean(r*r)):6.1f}  (+-t0 {perr[1]:.4f}, +-g {perr[2]:.4f})")
        return popt

print("=== SHIFT space, Lorentzian + LINEAR baseline ===")
for half in [60,80,100,120,150,200]: go(ss,1580.0,half,f"G shift half={half}")
for half in [80,100,120,150,180,220]: go(ss,2670.0,half,f"2D shift half={half}")
print("\n=== SHIFT space, Lorentzian + CONSTANT offset (4-param) ===")
for half in [60,80,100,120,150]: go(ss,1580.0,half,f"G shift half={half}",lin=False)
for half in [80,100,120,150,180]: go(ss,2670.0,half,f"2D shift half={half}",lin=False)
print("\n=== X space, Lorentzian + LINEAR baseline ===")
for half in [120,150,200,250,300]: go(xs,6329.0,half,f"G x half={half}")
for half in [80,100,130,160,200]: go(xs,3745.0,half,f"2D x half={half}")
print("\n=== X space, Lorentzian + CONSTANT offset (4-param) ===")
for half in [120,150,200,250,300]: go(xs,6329.0,half,f"G x half={half}",lin=False)
for half in [80,100,130,160,200]: go(xs,3745.0,half,f"2D x half={half}",lin=False)
